CREATE VIEW dept20_check AS
SELECT * FROM EMP WHERE DEPTNO = 20
WITH CHECK OPTION;

CREATE VIEW sal2000_check AS
SELECT * FROM EMP WHERE SAL > 2000
WITH CHECK OPTION;

CREATE VIEW emp_readonly AS
SELECT * FROM EMP
WITH READ ONLY;

CREATE VIEW emp_dept_readonly AS
SELECT e.ENAME, d.DNAME FROM EMP e, DEPT d WHERE e.DEPTNO = d.DEPTNO
WITH READ ONLY;

CREATE VIEW dept10_readonly AS
SELECT * FROM EMP WHERE DEPTNO = 10
WITH READ ONLY;

CREATE MATERIALIZED VIEW mv_complete
REFRESH COMPLETE
AS SELECT * FROM EMP;

CREATE MATERIALIZED VIEW mv_fast
REFRESH FAST
AS SELECT * FROM EMP;

CREATE MATERIALIZED VIEW mv_commit
REFRESH ON COMMIT
AS SELECT * FROM EMP;

CREATE MATERIALIZED VIEW mv_imm
BUILD IMMEDIATE
AS SELECT * FROM EMP;

CREATE MATERIALIZED VIEW mv_def
BUILD DEFERRED
AS SELECT * FROM EMP;

CREATE VIEW dept_max_sal AS
SELECT d.DNAME, MAX(e.SAL) AS MAX_SAL FROM EMP e, DEPT d 
WHERE e.DEPTNO = d.DEPTNO GROUP BY d.DNAME;

CREATE MATERIALIZED VIEW mv_complex AS
SELECT d.DNAME, MAX(e.SAL) FROM EMP e, DEPT d 
WHERE e.DEPTNO = d.DEPTNO GROUP BY d.DNAME;
